import random

def check_range(start, end):
    for n in range(start, end+1):
        if (n * (n+1)) % 2 != 0:
            return False, n
    return True, None

# 检查一些范围
ranges = [(-100, 100), (-1000, -900), (900, 1000)]
all_pass = True
for start, end in ranges:
    passed, bad_n = check_range(start, end)
    if not passed:
        print(f"Failed at n={bad_n}")
        all_pass = False
        break
    else:
        print(f"Range {start} to {end}: all even")
if all_pass:
    print("All tested ranges passed: n(n+1) is even.")
